import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

var names = ['Грузовики', 'Легковые', 'Спецтехника', 'Автобусы', 'Прицепы'];
function App() {
    var selected = React.useState(['Грузовики']);
    return <div className="dschipgroup-example">
    <style>{exampleStyles}</style>
    <div className={"demo-stack"}>
    <S.DsChipGroup ariaLabel={'Типы объектов'} onClearAll={selected[0].length ? function () { selected[1]([]); document.querySelector('[role="group"][aria-label="Типы объектов"] button').focus(); } : undefined} clearAllLabel={'Снять выбор'}>
    {names.map(function (name) {
            return <S.DsChip key={name} selected={selected[0].includes(name)} onClick={function () { selected[1](selected[0].includes(name) ? selected[0].filter(function (n) { return n !== name; }) : selected[0].concat(name)); }}>
    {name}
    </S.DsChip>;
        })}
    </S.DsChipGroup>
    <p className={'cap'} role={'status'}>
    {'Выбрано типов: ' + selected[0].length + '.'}
    </p>
    </div>
    </div>;
}

const exampleStyles = ".dschipgroup-example{font:var(--ds-type-body);color:var(--ds-fg)}\n.dschipgroup-example .demo-stack{display:flex;flex-direction:column;gap:16px;min-width:0}\n.dschipgroup-example p{margin:0}\n.dschipgroup-example .cap{font:var(--ds-type-caption);color:var(--ds-fg-muted);margin:0}";

export { App as Example };

