import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

var names = ['Грузовики', 'Легковые', 'Спецтехника', 'Автобусы', 'Прицепы'];
function App() {
    var values = React.useState(names), message = React.useState('');
    function update(next, text) { values[1](next); message[1](text); document.getElementById('restore-group').focus(); }
    return <div className="dschipgroup-example">
    <style>{exampleStyles}</style>
    <div className={"demo-stack"}>
    <div>
    <S.DsButton id={'restore-group'} tone={'secondary'} size={'sm'} onClick={function () { values[1](names); message[1]('Группы восстановлены.'); }}>
    {'Восстановить группы'}
    </S.DsButton>
    </div>
    <S.DsChipGroup ariaLabel={'Выбранные группы'} onClearAll={function () { update([], 'Все группы удалены.'); }}>
    {values[0].map(function (name) {
            return <S.DsChip key={name} removable={true} onRemove={function () { update(values[0].filter(function (n) { return n !== name; }), 'Удалена группа «' + name + '».'); }}>
    {name}
    </S.DsChip>;
        })}
    </S.DsChipGroup>
    <p className={'cap'} role={'status'}>
    {message[0] || 'Удалите отдельную группу или очистите все.'}
    </p>
    </div>
    </div>;
}

const exampleStyles = ".dschipgroup-example{font:var(--ds-type-body);color:var(--ds-fg)}\n.dschipgroup-example .demo-stack{display:flex;flex-direction:column;gap:16px;min-width:0}\n.dschipgroup-example p{margin:0}\n.dschipgroup-example .cap{font:var(--ds-type-caption);color:var(--ds-fg-muted);margin:0}";

export { App as Example };

